	(7,'FP2026042502',NULL,1,2,2,'mixed_product','严格低硫订单最终商品煤',3200.00,3200.00,'FINAL-WH-02',13.18,0.610,7.25,33.10,5735.00,'used','订单O2026042502最终商品煤，硫分略超目标上限，作为风险场景','2026-04-25 16:14:38','2026-04-25 16:14:38'),
	(8,'PB-REAL-JJT-20260427-CL',1,1,NULL,NULL,'clean_coal','金鸡滩低灰低硫精煤补充批次',6800.00,6800.00,'PROD-WH-JJT-REAL',7.80,0.700,6.80,31.50,6250.00,'available','参考公开资料：金鸡滩煤矿原煤低灰低硫，发热量约6177-6325kcal/kg；用于低硫高热值订单候选。','2026-04-25 17:26:16','2026-04-25 17:26:16'),
	(9,'PB-REAL-YPH-20260427-CL',1,3,NULL,NULL,'clean_coal','营盘壕高热值精煤补充批次',5600.00,5600.00,'PROD-WH-YPH-REAL',8.90,0.680,5.60,32.80,6988.00,'available','参考公开资料：营盘壕煤发热量约29.21MJ/kg，折合约6988kcal/kg；用于高热值补偿。','2026-04-25 17:26:16','2026-04-25 17:26:16'),
	(10,'PB-REAL-PS-20260427-CL',2,4,NULL,NULL,'clean_coal','平朔洗选动力煤补充批次',5200.00,5200.00,'PROD-WH-PS-REAL',21.00,1.100,11.50,30.00,5200.00,'available','参考平朔动力煤公开指标构造：灰分约21%、硫分约1.1%、水分约11.5%、发热量约5200kcal/kg；适合宽硫成本型订单。','2026-04-25 17:26:16','2026-04-25 17:26:16'),
	(11,'PB-REAL-WCW-20260427-CL',3,5,NULL,NULL,'clean_coal','准东五彩湾低硫动力煤补充批次',6200.00,6200.00,'PROD-WH-WCW-REAL',6.43,0.510,11.17,27.91,4850.00,'available','参考准东五彩湾煤公开工业分析：低灰、低硫、水分较高；用于低成本候选并触发水分风险提示。','2026-04-25 17:26:16','2026-04-25 17:26:16');

/*!40000 ALTER TABLE `product_batch` ENABLE KEYS */;
